using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Academy.Api.Auth;
using Academy.Api.Slice5;
using Academy.Infrastructure.Evaluations;
using Academy.Infrastructure.Persistence;
using Academy.Infrastructure.Tenancy;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
namespace Academy.IntegrationTests;
public sealed partial class BrandingMatchesTests
{
    private const string Certificates="/api/v1/evaluations/certificates";
    [Fact] public async Task Certificate_scoped_admin_requires_live_add_to_issue_edit_to_withdraw_and_scope_before_replay()=>await DelegateFixture(async(owner,admin,db,group,member)=>{
        using var coach=await Mobile(AcademyRole.Coach);var(f,rid,target)=await PromotionSetup(owner,coach,db,group);(await Send(owner,$"{Technical}/{rid}/promotion",await PromotionBody(owner,rid,target))).EnsureSuccessStatusCode();var source=await db.PlayerLevelReviews.AsNoTracking().SingleAsync(r=>r.SportEnrollmentId==f.Enrollment&&r.TechnicalDecisionId!=null);
        var grant=await db.StaffActionGrants.SingleOrDefaultAsync(g=>g.MembershipId==member&&g.Module=="evaluations");var old=grant==null?null:JsonSerializer.Serialize(grant);grant??=new(){Id=Guid.NewGuid(),AcademyId=group.AcademyId,MembershipId=member,Module="evaluations"};if(old==null)db.StaffActionGrants.Add(grant);grant.IsActive=true;grant.Read=true;grant.Add=false;grant.Edit=true;grant.Delete=false;
        try{
            await db.SaveChangesAsync();var issue=new CertificateIssueWrite(source.Version,Guid.NewGuid());var path=$"{Certificates}/sources/{source.Id}/issue";Assert.False((await admin.GetFromJsonAsync<JsonElement>($"{Certificates}/sources/{source.Id}")).GetProperty("canIssue").GetBoolean());Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,path,issue)).StatusCode);
            grant.Add=true;grant.Edit=false;await db.SaveChangesAsync();var response=await Send(admin,path,issue);Assert.Equal(HttpStatusCode.Created,response.StatusCode);var id=(await response.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();var c=await admin.GetFromJsonAsync<JsonElement>($"{Certificates}/{id}");var withdraw=new CertificateWithdrawWrite(c.GetProperty("certificate").GetProperty("version").GetUInt32(),null,Guid.NewGuid());Assert.False(c.GetProperty("canWithdraw").GetBoolean());Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Certificates}/{id}/withdraw",withdraw)).StatusCode);
            grant.Add=false;grant.Edit=true;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,path,issue)).StatusCode);(await Send(admin,$"{Certificates}/{id}/withdraw",withdraw)).EnsureSuccessStatusCode();grant.Edit=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await Send(admin,$"{Certificates}/{id}/withdraw",withdraw)).StatusCode);
            grant.Add=true;grant.Edit=true;await db.SaveChangesAsync();var branch=await db.MembershipBranchAccesses.SingleAsync(b=>b.MembershipId==member&&b.BranchId==group.BranchId);branch.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync($"{Certificates}/{id}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(admin,path,issue)).StatusCode);branch.IsActive=true;await db.SaveChangesAsync();var sport=await db.MembershipSportAccesses.SingleAsync(s=>s.MembershipId==member&&s.SportId==group.SportId);sport.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync($"{Certificates}/{id}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(admin,$"{Certificates}/{id}/withdraw",withdraw)).StatusCode);sport.IsActive=true;await db.SaveChangesAsync();
            grant.Read=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync($"{Certificates}/{id}")).StatusCode);
        }finally{if(old==null)db.StaffActionGrants.Remove(grant);else db.Entry(grant).CurrentValues.SetValues(JsonSerializer.Deserialize<StaffActionGrant>(old)!);await db.SaveChangesAsync();}
    });
    [Fact]public async Task Certificate_requires_applied_promotion_publishes_fixed_snapshots_and_withdraws_without_reversing_history_or_money()
    {
        using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);using var family=await Mobile(AcademyRole.Guardian);using var foreign=await Staff(DemoSeed.FutureOwnerEmail);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var(f,rid,target)=await PromotionSetup(owner,coach,db);
        var manual=await db.PlayerLevelReviews.AsNoTracking().SingleAsync(r=>r.SportEnrollmentId==f.Enrollment);var badSource=await owner.GetFromJsonAsync<JsonElement>($"{Certificates}/sources/{manual.Id}");Assert.False(badSource.GetProperty("canIssue").GetBoolean());Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Certificates}/sources/{manual.Id}/issue",new CertificateIssueWrite(manual.Version,Guid.NewGuid()))).StatusCode);
        var promotion=await PromotionBody(owner,rid,target);(await Send(owner,$"{Technical}/{rid}/promotion",promotion)).EnsureSuccessStatusCode();var source=await db.PlayerLevelReviews.AsNoTracking().SingleAsync(r=>r.SportEnrollmentId==f.Enrollment&&r.TechnicalDecisionId!=null);var path=$"{Certificates}/sources/{source.Id}/issue";var body=new CertificateIssueWrite(source.Version,Guid.NewGuid());
        var cash=await db.Collections.CountAsync();var periods=await db.SubscriptionPeriods.CountAsync();var levelCount=await db.PlayerLevelReviews.CountAsync();var transfers=await db.EnrollmentGroupTransfers.CountAsync();var report=await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28");
        Assert.Equal(HttpStatusCode.BadRequest,(await owner.PostAsJsonAsync(path,body)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(coach,path,body)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await Send(family,path,body)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await Send(foreign,path,body)).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,path,body with{SourceVersion=source.Version+1})).StatusCode);
        var issued=await Send(owner,path,body);Assert.Equal(HttpStatusCode.Created,issued.StatusCode);var id=(await issued.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid();Assert.Equal(id,(await(await Send(owner,path,body)).Content.ReadFromJsonAsync<JsonElement>()).GetProperty("id").GetGuid());Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,path,body with{RequestId=Guid.NewGuid()})).StatusCode);
        var url=$"/api/v1/guardian/children/{f.Player}/certificates/{id}";var publicCert=(await family.GetFromJsonAsync<JsonElement>(url)).GetProperty("certificate");Assert.Equal(source.ToLevelName,publicCert.GetProperty("levelName").GetString());Assert.Equal("Issued",publicCert.GetProperty("state").GetString());Assert.Equal("لاعب رحلة مهارات اصطناعي",publicCert.GetProperty("playerName").GetString());Assert.DoesNotContain("privateNote",publicCert.GetRawText());Assert.Single((await family.GetFromJsonAsync<JsonElement>($"/api/v1/guardian/children/{f.Player}/certificates")).GetProperty("items").EnumerateArray());Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync($"/api/v1/guardian/children/{Guid.NewGuid()}/certificates/{id}")).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync($"{Certificates}/{id}")).StatusCode);
        (await db.Players.SingleAsync(p=>p.Id==f.Player)).ArabicName="اسم أحدث للاعب الاصطناعي";(await db.TrainingLevels.SingleAsync(l=>l.Id==f.Next)).ArabicName="اسم أحدث للمستوى "+Guid.NewGuid().ToString("N")[..6];await db.SaveChangesAsync();Assert.Equal(publicCert.GetProperty("playerName").GetString(),(await family.GetFromJsonAsync<JsonElement>(url)).GetProperty("certificate").GetProperty("playerName").GetString());Assert.Equal(source.ToLevelName,(await family.GetFromJsonAsync<JsonElement>(url)).GetProperty("certificate").GetProperty("levelName").GetString());
        var withdrawal=new CertificateWithdrawWrite(publicCert.GetProperty("version").GetUInt32(),null,Guid.NewGuid());Assert.Equal(HttpStatusCode.Forbidden,(await Send(coach,$"{Certificates}/{id}/withdraw",withdrawal)).StatusCode);(await Send(owner,$"{Certificates}/{id}/withdraw",withdrawal)).EnsureSuccessStatusCode();(await Send(owner,$"{Certificates}/{id}/withdraw",withdrawal)).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Conflict,(await Send(owner,$"{Certificates}/{id}/withdraw",withdrawal with{FamilyNote="تغيير نفس المفتاح"})).StatusCode);Assert.Equal("Withdrawn",(await family.GetFromJsonAsync<JsonElement>(url)).GetProperty("certificate").GetProperty("state").GetString());Assert.False((await owner.GetFromJsonAsync<JsonElement>($"{Certificates}/{id}")).GetProperty("canWithdraw").GetBoolean());
        Assert.Equal(cash,await db.Collections.CountAsync());Assert.Equal(periods,await db.SubscriptionPeriods.CountAsync());Assert.Equal(levelCount,await db.PlayerLevelReviews.CountAsync());Assert.Equal(transfers,await db.EnrollmentGroupTransfers.CountAsync());Assert.Equal(report,await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28"));
        var forged=await db.PlayerAchievementCertificates.AsNoTracking().SingleAsync(c=>c.Id==id);forged.Id=Guid.NewGuid();forged.RequestId=Guid.NewGuid();forged.SourceLevelReviewId=manual.Id;db.PlayerAchievementCertificates.Add(forged);var invalid=await Assert.ThrowsAsync<DbUpdateException>(()=>db.SaveChangesAsync());Assert.Equal("23514",Assert.IsType<Npgsql.PostgresException>(invalid.InnerException).SqlState);db.ChangeTracker.Clear();
        var c=await db.PlayerAchievementCertificates.SingleAsync(c=>c.Id==id);c.PlayerName="تغيير المصدر";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());db.ChangeTracker.Clear();var sql=await Assert.ThrowsAsync<Npgsql.PostgresException>(()=>db.Database.ExecuteSqlInterpolatedAsync($"DELETE FROM \"PlayerCertificateWithdrawals\" WHERE \"CertificateId\"={id}"));Assert.Equal("23514",sql.SqlState);
        var link=await db.GuardianPlayerLinks.SingleAsync(l=>l.PlayerId==f.Player);link.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync(url)).StatusCode);
    }
}
